// VIOC_units_extra.sqf - agregado por tools/vio_build.py, parche "units_extra_qav" (copia configurada, no es del
// autor de la mision). Lo llama Init_Common.sqf una vez por bando (west y east), cuando ya estan todas las fabricas y
// escuadras, en cada maquina (servidor y clientes), como el resto de Init_Common.
// Suma vehiculos del mod "QAV - Vanilla Vehicle Expansion" (Workshop 3630109865, carpeta @nue) al menu de compra:
//  - AMV-7 Marshall (APC, MGS, MGS-UP) y AMV-7A Guardian en la fabrica ligera; MV-35 Phantom en la aerea;
//  - solo si la clase existe (mod cargado), es publica (scope 2) y nadie la definio antes; sin el mod no hace nada;
//  - version oliva (B_T_) en mapas boscosos o si "Main Camo" pide invierno/selva; arena (B_) en el resto o con
//    "Main Camo" desierto. El selector de camuflaje del menu de compra igual deja cambiarla;
//  - no crea niveles de mejora: el rango 0, 1, 2.. es el 1.o, 2.o, 3.o.. nivel que YA usa esa fabrica para ese
//    bando; -1 es el ultimo, -2 el penultimo... Si una clase de referencia ya esta en esa fabrica (M1128 MGS, Stryker
//    ATGM, MV-22, Rhino, Blackfish...), toma su nivel;
//  - precio y tiempo con las formulas del autor: [CTI_ECONOMY_PRIZE_<tipo>, nivel, armado, multiplicador]
//    call CTI_CO_FNC_GetCalculatedUnitsPrize y [CTI_FACTORY_<tipo>, nivel] call CTI_CO_FNC_GetCalculatedBuildtime;
//  - la tripulacion la pone la mision al comprar (CTI_<bando>_Soldier/Crew/Pilot), no el vehiculo.
// Solo el menu de compra: la IA comandante y sus escuadras siguen con los vehiculos de su nacion.
// Parametro de lobby VIOC_QAV_VEHICLES: 0 = no; 1 = si (EE.UU. en las misiones CW, OTAN en la clasica; por defecto,
// tambien en "Un jugador", donde la mision no lee el lobby); 2 = tambien si el Oeste es Ucrania (misiones CW).
private ["_side", "_faction", "_classname", "_get", "_turret_main", "_turret_sub", "_roleFound"];
_side = _this;
_faction = "";
private _vioc_mode = missionNamespace getVariable ["VIOC_QAV_VEHICLES", 1];
if (_vioc_mode <= 0 || {!(_side in [west, east])}) exitWith {};
private _vioc_keys = [];
if (isNil "CTI_US_SIDE") then {
	if (_side == west) then {_vioc_keys pushBack "NATO"};
} else {
	if (CTI_US_SIDE >= 0 && {((CTI_US_SIDE) call CTI_CO_FNC_GetSideFromID) == _side}) then {_vioc_keys pushBack "US"};
	if (_vioc_mode >= 2 && {!isNil "CTI_UKRAIN_SIDE"} && {CTI_UKRAIN_SIDE >= 0} && {((CTI_UKRAIN_SIDE) call CTI_CO_FNC_GetSideFromID) == _side}) then {_vioc_keys pushBack "UA"};
};
if (count _vioc_keys == 0) exitWith {};
private _vioc_fac = [
	["LIGHT", CTI_LIGHT, CTI_FACTORY_LIGHT, CTI_ECONOMY_PRIZE_WHEELED],
	["HEAVY", CTI_HEAVY, CTI_FACTORY_HEAVY, CTI_ECONOMY_PRIZE_TRACKED],
	["AIR", CTI_AIR, CTI_FACTORY_AIR, CTI_ECONOMY_PRIZE_AIR],
	["NAVAL", CTI_NAVAL, CTI_FACTORY_NAVAL, CTI_ECONOMY_PRIZE_NAVAL]
];
private _vioc_green = (toLower worldName) in ["chernarus", "chernarus_summer", "chernarus_winter", "cup_chernarus_a3", "enoch", "tanoa", "sara", "saralite", "sara_dbe1", "woodland_acr", "bootcamp_acr", "provinggrounds_pmc", "porto", "intro", "eden", "cain", "abel", "noe", "gm_weferlingen_summer", "gm_weferlingen_winter", "cam_lao_nam", "vn_khe_sanh", "vn_the_bra", "stozec"];
if (!isNil "CTI_CAMO_ACTIVATION") then {
	if (isNil "CTI_US_SIDE") then {
		if (CTI_CAMO_ACTIVATION == 1) then {_vioc_green = true}; //--- clasica: "Jungle (APEX)" = sus vehiculos B_T_
	} else {
		if (CTI_CAMO_ACTIVATION == 2) then {_vioc_green = false}; //--- CW: "Desert"
		if (CTI_CAMO_ACTIVATION in [1, 3]) then {_vioc_green = true}; //--- CW: "Winter" y "Jungle"
	};
};
private _vioc_added = [];
{
	private _vioc_list = switch (_x) do {
		case "US": {[
			[["APC_Wheeled_01_apc_qav", "B_T_APC_Wheeled_01_apc_QAV"], "LIGHT", -2, true, 1.25, ["CUP_B_M1135_ATGMV_Woodland", "CUP_B_M1135_ATGMV_Desert", "rhsusf_stryker_m1134_wd"]],
			[["APC_Wheeled_01_mgs_QAV", "B_T_APC_Wheeled_01_mgs_QAV"], "LIGHT", -1, true, 1.25, ["CUP_B_M1128_MGS_Woodland", "CUP_B_M1128_MGS_Desert"]],
			[["APC_Wheeled_01_mgs_up_QAV", "B_T_APC_Wheeled_01_mgs_up_QAV"], "LIGHT", -1, true, 1.5, ["CUP_B_M1128_MGS_Woodland", "CUP_B_M1128_MGS_Desert"]],
			[["APC_Wheeled_01_shorad_QAV", "B_T_APC_Wheeled_01_shorad_QAV"], "LIGHT", -2, true, 1.25],
			[["B_VTOL_03_unarmed_QAV", "B_T_VTOL_03_unarmed_QAV"], "AIR", -2, false, 1, ["CUP_B_MV22_USMC", "CUP_B_MV22_VIV_USMC"]]
		]};
		case "UA": {[
			[["APC_Wheeled_01_apc_qav", "B_T_APC_Wheeled_01_apc_QAV"], "LIGHT", -2, true, 1.25],
			[["APC_Wheeled_01_mgs_QAV", "B_T_APC_Wheeled_01_mgs_QAV"], "LIGHT", -1, true, 1.25],
			[["APC_Wheeled_01_mgs_up_QAV", "B_T_APC_Wheeled_01_mgs_up_QAV"], "LIGHT", -1, true, 1.5],
			[["APC_Wheeled_01_shorad_QAV", "B_T_APC_Wheeled_01_shorad_QAV"], "LIGHT", -1, true, 1.25, ["CUP_B_nM1097_AVENGER_AFU", "CUP_B_UAZ_AA_AFU"]],
			[["B_VTOL_03_unarmed_QAV", "B_T_VTOL_03_unarmed_QAV"], "AIR", -1, false, 1]
		]};
		case "NATO": {[
			[["APC_Wheeled_01_apc_qav", "B_T_APC_Wheeled_01_apc_QAV"], "LIGHT", -3, true, 1.25, ["B_APC_Wheeled_01_cannon_F", "B_T_APC_Wheeled_01_cannon_F"]],
			[["APC_Wheeled_01_mgs_QAV", "B_T_APC_Wheeled_01_mgs_QAV"], "LIGHT", -2, true, 1.25, ["B_AFV_Wheeled_01_cannon_F", "B_T_AFV_Wheeled_01_cannon_F"]],
			[["APC_Wheeled_01_mgs_up_QAV", "B_T_APC_Wheeled_01_mgs_up_QAV"], "LIGHT", -1, true, 1.25, ["B_AFV_Wheeled_01_up_cannon_F", "B_T_AFV_Wheeled_01_up_cannon_F"]],
			[["APC_Wheeled_01_shorad_QAV", "B_T_APC_Wheeled_01_shorad_QAV"], "LIGHT", -2, true, 1.25],
			[["B_VTOL_03_unarmed_QAV", "B_T_VTOL_03_unarmed_QAV"], "AIR", -1, false, 1, ["B_T_VTOL_01_infantry_F"]]
		]};
		default {[]};
	};
	{
		private _vioc_e = _x;
		private _vioc_cls = _vioc_e select 0;
		if (typeName _vioc_cls == "ARRAY") then {
			_vioc_cls = if (_vioc_green && {isClass (configFile >> "CfgVehicles" >> (_vioc_cls select 1))}) then {_vioc_cls select 1} else {_vioc_cls select 0};
		};
		private _vioc_f = _vioc_e select 1;
		private _vioc_rank = _vioc_e select 2;
		private _vioc_armed = _vioc_e select 3;
		private _vioc_mult = _vioc_e select 4;
		private _vioc_refs = if (count _vioc_e > 5) then {_vioc_e select 5} else {[]};
		private _vioc_fi = -1;
		{ if ((_x select 0) == _vioc_f) then {_vioc_fi = _forEachIndex} } forEach _vioc_fac;
		if (_vioc_fi >= 0 && {isClass (configFile >> "CfgVehicles" >> _vioc_cls)} && {getNumber (configFile >> "CfgVehicles" >> _vioc_cls >> "scope") >= 2} && {isNil {missionNamespace getVariable _vioc_cls}}) then {
			private _vioc_type = (_vioc_fac select _vioc_fi) select 1;
			private _vioc_fconst = (_vioc_fac select _vioc_fi) select 2;
			private _vioc_base = (_vioc_fac select _vioc_fi) select 3;
			private _vioc_var = format ["CTI_%1_%2Units", _side, _vioc_type];
			private _vioc_units = missionNamespace getVariable [_vioc_var, []];
			private _vioc_levels = [];
			{
				private _vioc_v = missionNamespace getVariable _x;
				if (!isNil "_vioc_v") then {_vioc_levels pushBackUnique (missionNamespace getVariable [format ["VIOC_ULVL_%1", _x], _vioc_v select CTI_UNIT_UPGRADE])}; //--- nivel original (vehicles_start lo baja a 0)
			} forEach _vioc_units;
			if (count _vioc_levels > 0) then {
				_vioc_levels sort true;
				private _vioc_n = count _vioc_levels;
				private _vioc_lvl = if (_vioc_rank < 0) then {_vioc_levels select ((_vioc_n + _vioc_rank) max 0)} else {_vioc_levels select (_vioc_rank min (_vioc_n - 1))};
				private _vioc_done = false;
				{
					if (!_vioc_done && {_x in _vioc_units}) then {
						private _vioc_r = missionNamespace getVariable _x;
						if (!isNil "_vioc_r") then {_vioc_lvl = missionNamespace getVariable [format ["VIOC_ULVL_%1", _x], _vioc_r select CTI_UNIT_UPGRADE]; _vioc_done = true};
					};
				} forEach _vioc_refs;
				private _vioc_price = [_vioc_base, _vioc_lvl, _vioc_armed, _vioc_mult] call CTI_CO_FNC_GetCalculatedUnitsPrize;
				private _vioc_time = [_vioc_fconst, _vioc_lvl] call CTI_CO_FNC_GetCalculatedBuildtime;
				[_side, _faction, [_vioc_cls], [""], [""], [_vioc_price], [_vioc_time], [_vioc_lvl], [_vioc_fconst], [""], [10]] call compile preprocessFileLineNumbers "Common\Config\Units\Set_Units.sqf";
				if (!isNil {missionNamespace getVariable _vioc_cls} && {!(_vioc_cls in _vioc_units)}) then {
					_vioc_units pushBack _vioc_cls;
					missionNamespace setVariable [_vioc_var, _vioc_units];
					_vioc_added pushBack [_vioc_cls, _vioc_lvl, _vioc_price];
				};
			};
		};
	} forEach _vioc_list;
} forEach _vioc_keys;
if (CTI_Log_Level >= CTI_Log_Information) then {["INFORMATION", "FILE: Common\Config\Units\VIOC_units_extra.sqf", format ["[%1] %2: %3", _side, _vioc_keys, _vioc_added]] call CTI_CO_FNC_Log};

class VIOC_QAV_VEHICLES {
		title = "VIOC: Vehiculos QAV en las fabricas del Oeste (Marshall MGS/APC, Guardian AA, MV-35)";
		values[] = {0,1,2};
		texts[] = {"No","Si (EE.UU. en las CW, OTAN en la clasica)","Si, tambien si el Oeste es Ucrania"};
		default = 1;
	};
